<div style="font-size:10px;color:#777;line-height:1.35;margin-top:2px;">Drag to orbit: each plane is a real 2D projection seen obliquely &mdash; overlaps that look like mixing can be a viewpoint artifact.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── element spec ──────────────────────────────────────────────────────────
// plane quad       → PlaneGeometry(6,6) rotX(-90°), white, opacity .62, depthWrite:false
// plane border     → 2× LineLoop (4 corners), #4a4a4a  (+ accent ring when focused)
// plane crosshair  → LineSegments (X line + Z line through centre), #e0e0e0
// points           → InstancedMesh(SphereGeometry(0.14,10,8)) × 5 planes, 250 instances,
//                    OPAQUE MeshBasicMaterial + instanceColor (saturated class hues)
// connectors       → LineSegments per (class,gap): CatmullRomCurve3 sampled, alternate spans = dashes
// legend box       → ShapeGeometry (rounded rect 5.0×1.7) white fill + double LineLoop outline black
// legend arrow     → ShapeGeometry (shaft+head polygon) black, 5 of them, top one extra long
// legend text      → addLabel 'ViT block x3', monospace
// legend pose      → yaw-only billboard, orbits with the camera so it stays screen-left
// ──────────────────────────────────────────────────────────────────────────

const GAP = 4.5;                                   // vertical spacing (source: diamonds nearly touch)
const PLANE_Y = [0, GAP, 2 * GAP, 3 * GAP, 4 * GAP];
const STACK_CY = PLANE_Y[2];
const HALF = 3;                                    // plane is 6 × 6
const WHITE = new THREE.Color(0xffffff);

const CLASSES = [
  { name: 'blue',    color: 0x2f7fd0 },
  { name: 'olive',   color: 0xb5bd35 },
  { name: 'green',   color: 0x33b464 },
  { name: 'teal',    color: 0x2ec4c4 },
  { name: 'orange',  color: 0xf57f20 },
  { name: 'red',     color: 0xe03030 },
  { name: 'brown',   color: 0x8a6a5a },
  { name: 'purple',  color: 0x9b8ec4 },
  { name: 'magenta', color: 0xe84f9a },
  { name: 'pink',    color: 0xf0a0c0 },
];
const NC = CLASSES.length, PER = 25, NPT = NC * PER;
const CLS_COLOR = CLASSES.map(c => new THREE.Color(c.color));

/* ── deterministic RNG ─────────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20240917);

/* ── point layout per layer ────────────────────────────────────────────── */
// top plane: ten compact clumps in a shallow arc across the far (-Z) half
const clump = [];
for (let j = 0; j < NC; j++) {
  const t = j / (NC - 1);
  clump.push({
    x: -2.62 + t * 5.24,
    z: -1.55 + 0.6 * Math.sin(Math.PI * t) + (j % 2 ? 0.10 : -0.10),
  });
}
const BAND = [
  { w: 3.5, d: 0.50, ox: 0.0, oz: 0.0, j: 0.10 },   // y=0   tight mixed band
  { w: 4.5, d: 1.20, ox: 0.0, oz: 0.0, j: 0.30 },   // y=4.5
  { w: 4.5, d: 1.20, ox: -0.3, oz: 0.3, j: 0.30 },  // y=9   drifts near/left
  { w: 5.0, d: 1.50, ox: 0.0, oz: 0.0, j: 0.35 },   // y=13.5
  { w: 5.0, d: 1.50, ox: 0.0, oz: 0.0, j: 0.00 },   // y=18  (unused, g=1)
];
const G = [0, 0.12, 0.30, 0.62, 1.0];   // class-grouping strength per layer

const PTS = [];
for (let i = 0; i < NPT; i++) {
  const cls = i % NC;                      // fully interleaved at the bottom
  const u = rnd(), v = rnd();
  const jit = [];
  for (let k = 0; k < 5; k++) jit.push([rnd() - 0.5, rnd() - 0.5]);
  const cc = clump[cls];
  const top = { x: cc.x + (rnd() - 0.5) * 0.52, z: cc.z + (rnd() - 0.5) * 0.44 };
  const layers = [];
  for (let k = 0; k < 5; k++) {
    const B = BAND[k], g = G[k];
    const bx = (u - 0.5) * B.w + B.ox + jit[k][0] * B.j;
    const bz = (v - 0.5) * B.d + B.oz + jit[k][1] * B.j;
    layers.push(new THREE.Vector3(
      bx * (1 - g) + top.x * g,
      PLANE_Y[k],
      bz * (1 - g) + top.z * g));
  }
  PTS.push({ cls, layers });
}

/* ── planes ────────────────────────────────────────────────────────────── */
const planes = [];
for (let k = 0; k < 5; k++) {
  const y = PLANE_Y[k];
  const g = new THREE.Group();

  const quadMat = new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0.62,
    depthWrite: false, side: THREE.DoubleSide,
  });
  const quadGeo = new THREE.PlaneGeometry(2 * HALF, 2 * HALF);
  quadGeo.rotateX(-Math.PI / 2);
  const quad = new THREE.Mesh(quadGeo, quadMat);
  quad.position.y = y;
  quad.renderOrder = 2;
  g.add(quad);

  const gridMat = new THREE.LineBasicMaterial({
    color: 0xe0e0e0, transparent: true, opacity: 0.95, depthWrite: false,
  });
  const gridGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-HALF, y + 0.01, 0), new THREE.Vector3(HALF, y + 0.01, 0),
    new THREE.Vector3(0, y + 0.01, -HALF), new THREE.Vector3(0, y + 0.01, HALF),
  ]);
  const grid = new THREE.LineSegments(gridGeo, gridMat);
  grid.renderOrder = 3;
  g.add(grid);

  const borMat = new THREE.LineBasicMaterial({
    color: 0x4a4a4a, transparent: true, opacity: 1, depthWrite: false,
  });
  const corners = [
    new THREE.Vector3(-HALF, y + 0.015, -HALF), new THREE.Vector3(HALF, y + 0.015, -HALF),
    new THREE.Vector3(HALF, y + 0.015, HALF), new THREE.Vector3(-HALF, y + 0.015, HALF),
  ];
  for (const s of [1.0, 0.993, 0.986]) {
    const geo = new THREE.BufferGeometry().setFromPoints(
      corners.map(c => new THREE.Vector3(c.x * s, c.y, c.z * s)));
    const ll = new THREE.LineLoop(geo, borMat);
    ll.renderOrder = 4;
    g.add(ll);
  }
  // accent ring, shown only on the focused plane
  const accMat = new THREE.LineBasicMaterial({ color: 0x1f6fd0, transparent: true, depthWrite: false });
  const ring = new THREE.Group();
  for (const s of [1.012, 1.005]) {
    const geo = new THREE.BufferGeometry().setFromPoints(
      corners.map(c => new THREE.Vector3(c.x * s, c.y, c.z * s)));
    const ll = new THREE.LineLoop(geo, accMat);
    ll.renderOrder = 5;
    ring.add(ll);
  }
  ring.visible = false;
  g.add(ring);

  scene.add(g);
  planes.push({ group: g, quadMat, borMat, ring });
}

/* ── scatter points (one InstancedMesh per plane, OPAQUE → saturated) ──── */
const PT_R = 0.14;
const ptGeo = new THREE.SphereGeometry(PT_R, 10, 8);
const dummy = new THREE.Object3D();
const pointMeshes = [];
for (let k = 0; k < 5; k++) {
  const mat = new THREE.MeshBasicMaterial({ transparent: false, depthWrite: true });
  const mesh = new THREE.InstancedMesh(ptGeo, mat, NPT);
  mesh.frustumCulled = false;
  mesh.renderOrder = 1;
  for (let i = 0; i < NPT; i++) {
    const p = PTS[i].layers[k];
    dummy.position.set(p.x, p.y + PT_R * 0.9, p.z);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
    mesh.setColorAt(i, CLS_COLOR[PTS[i].cls]);
  }
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  mesh.userData.planeIdx = k;
  scene.add(mesh);
  pointMeshes.push(mesh);
}

/* ── dashed trajectories: one LineSegments per (class, gap) ────────────── */
const BOW = [0.25, -0.35, -0.30, 0.50];   // waist in the middle, flare at the top
const curveMeshes = [];                   // curveMeshes[gap][cls]
for (let gap = 0; gap < 4; gap++) {
  const perClass = [];
  for (let c = 0; c < NC; c++) perClass.push([]);
  for (let i = 0; i < NPT; i++) {
    const a = PTS[i].layers[gap], b = PTS[i].layers[gap + 1];
    const m1 = a.clone().lerp(b, 1 / 3), m2 = a.clone().lerp(b, 2 / 3);
    const rad = (p) => {
      const r = new THREE.Vector3(p.x, 0, p.z);
      if (r.lengthSq() < 1e-6) r.set(1, 0, 0);
      return r.normalize();
    };
    m1.addScaledVector(rad(m1), BOW[gap]);
    m2.addScaledVector(rad(m2), BOW[gap] * 0.75);
    const curve = new THREE.CatmullRomCurve3([a, m1, m2, b], false, 'catmullrom', 0.5);
    const len = curve.getLength();
    const nd = Math.max(8, Math.round(len / 0.50));
    const sp = curve.getSpacedPoints(nd * 2);
    const arr = perClass[PTS[i].cls];
    for (let j = 0; j < nd; j++) {           // keep alternate spans → dashes
      const p0 = sp[2 * j], p1 = sp[2 * j + 1];
      arr.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
    }
  }
  const row = [];
  for (let c = 0; c < NC; c++) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(perClass[c], 3));
    const mat = new THREE.LineBasicMaterial({
      color: CLS_COLOR[c].clone(), transparent: true, opacity: 0.65, depthWrite: false,
    });
    const ls = new THREE.LineSegments(geo, mat);
    ls.renderOrder = 0;
    scene.add(ls);
    row.push(ls);
  }
  curveMeshes.push(row);
}

/* ── legend column (yaw-billboard: always screen-left, text upright) ───── */
const LEG_R = 7.5;                 // screen-space distance left of the stack axis
const legendGroup = new THREE.Group();
legendGroup.position.set(-LEG_R * Math.SQRT1_2, STACK_CY, LEG_R * Math.SQRT1_2);
legendGroup.rotation.set(0, Math.PI / 4, 0);
scene.add(legendGroup);

function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}
const blackLine = new THREE.LineBasicMaterial({ color: 0x000000 });
