});
canvas.addEventListener('pointerleave', () => { hoverClass = -1; applyState(); });

/* ── demo ──────────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Patch embeddings (bottom plane)', narration: 'At the output of patch embedding, all ten classes occupy one narrow band — colors are completely interleaved and no class is linearly separable.', depth: 0 },
  { title: 'After the first three ViT blocks', narration: 'Following the dashed paths up one stage, the cloud spreads slightly but the colors remain thoroughly intermingled: three blocks alone barely untangle the classes.', depth: 1 },
  { title: 'Mid-network (blocks 4-6)', narration: 'By the middle plane, faint same-color neighborhoods start forming, yet most clusters still overlap — separation is emerging but incomplete.', depth: 2 },
  { title: 'Late blocks (7-9)', narration: 'Same-color points begin pulling together into recognizable groups while the dashed trajectories fan outward, showing the largest reorganization happens in the later blocks.', depth: 3 },
  { title: 'Final representation (top plane)', narration: 'On the top plane each class has collapsed into its own compact, single-colored clump — twelve transformer blocks have turned a tangled distribution into a class-separated one.', depth: 4 },
