let stepIdx = 0, demoTimer = null;
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  depth = s.depth;
  document.getElementById('narrTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + ' · ' + s.title;
  document.getElementById('narr').textContent = s.narration;
