  pv.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  rc.setFromCamera(pv, camera);
  const hits = rc.intersectObjects(pointMeshes, false);
  let c = -1;
  if (hits.length && hits[0].instanceId != null) c = PTS[hits[0].instanceId].cls;
  if (c !== hoverClass) { hoverClass = c; applyState(); }
  if (c >= 0) showTooltip('class: ' + CLASSES[c].name + '  (hover traces it through every plane)', ev);
});
canvas.addEventListener('pointerleave', () => { hoverClass = -1; applyState(); });

/* ── demo ──────────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Patch embeddings (bottom plane)', narration: 'At the output of patch embedding, all ten classes occupy one narrow band — colors are completely interleaved and no class is linearly separable.', depth: 0 },
  { title: 'After the first three ViT blocks', narration: 'Following the dashed paths up one stage, the cloud spreads slightly but the colors remain thoroughly intermingled: three blocks alone barely untangle the classes.', depth: 1 },
  { title: 'Mid-network (blocks 4-6)', narration: 'By the middle plane, faint same-color neighborhoods start forming, yet most clusters still overlap — separation is emerging but incomplete.', depth: 2 },
  { title: 'Late blocks (7-9)', narration: 'Same-color points begin pulling together into recognizable groups while the dashed trajectories fan outward, showing the largest reorganization happens in the later blocks.', depth: 3 },
  { title: 'Final representation (top plane)', narration: 'On the top plane each class has collapsed into its own compact, single-colored clump — twelve transformer blocks have turned a tangled distribution into a class-separated one.', depth: 4 },
];
let stepIdx = 0, demoTimer = null;
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  depth = s.depth;
  document.getElementById('narrTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + ' · ' + s.title;
  document.getElementById('narr').textContent = s.narration;
  applyState();
}
function stopDemo() {
  if (demoTimer) { clearInterval(demoTimer); demoTimer = null; }
  document.getElementById('btnPlay').textContent = '▶ Play demo';
}
document.getElementById('btnPlay').addEventListener('click', () => {
  if (demoTimer) { stopDemo(); return; }
  goToStep(0);
  document.getElementById('btnPlay').textContent = '❚❚ Pause';
  demoTimer = setInterval(() => goToStep(stepIdx + 1), 4200);
});
document.getElementById('btnNext').addEventListener('click', () => { stopDemo(); goToStep(stepIdx + 1); });

/* ── per-frame: keep the legend column screen-left and facing the viewer ─ */
const tmpV = new THREE.Vector3();
(function tickLegend() {
  requestAnimationFrame(tickLegend);
  const dx = camera.position.x - controls.target.x;
  const dz = camera.position.z - controls.target.z;
  const phi = Math.atan2(dx, dz);                 // horizontal camera bearing
  legendGroup.rotation.set(0, phi, 0);            // panel normal → camera (yaw only)
  legendGroup.position.set(-LEG_R * Math.cos(phi), STACK_CY, LEG_R * Math.sin(phi));
  legendGroup.updateMatrixWorld();
  for (const { lab, ly } of legendLabels) {
    tmpV.set(0, ly, 0.03);
    legendGroup.localToWorld(tmpV);
    lab.pos.copy(tmpV);
  }
})();

goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

