<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── element spec ──────────────────────────────────────────────────────────
// plane quad       → PlaneGeometry(6,6) rotX(-90°), white, opacity .60, depthWrite:false
// plane border     → 3× LineLoop (4 corners, slight insets), uniform dark grey #4f4f4f
// focus ring       → 2× LineLoop, muted blue, TRANSIENT only (fades out in ~1.3 s)
// plane crosshair  → LineSegments (X line + Z line through centre), #e2e2e2
// points           → InstancedMesh(SphereGeometry(0.135,10,8)) × 5 planes, 300 instances,
//                    OPAQUE MeshBasicMaterial + instanceColor (saturated class hues)
//                    layout: k0 dense interleaved 2-D cloud → k4 ten separated clumps
// connectors       → LineSegments per (class,gap): CatmullRomCurve3, alternate spans = dashes,
//                    lightened class colour, opacity .82
// legend box       → ShapeGeometry (rounded rect 5.0×1.7) white fill + double LineLoop outline black
// legend arrow     → ShapeGeometry (shaft+head polygon) black, 5 of them, top one extra long
// legend text      → addLabel 'ViT block x3', monospace
// legend pose      → yaw-only billboard, orbits with the camera so it stays screen-left
// ──────────────────────────────────────────────────────────────────────────

const GAP = 6.2;                                   // vertical spacing between planes
const PLANE_Y = [0, GAP, 2 * GAP, 3 * GAP, 4 * GAP];
const STACK_CY = PLANE_Y[2];
const HALF = 3;                                    // plane is 6 × 6
const WHITE = new THREE.Color(0xffffff);

const CLASSES = [
  { name: 'blue',    color: 0x2f7fd0 },
  { name: 'olive',   color: 0xb5bd35 },
  { name: 'green',   color: 0x33b464 },
  { name: 'teal',    color: 0x2ec4c4 },
  { name: 'orange',  color: 0xf57f20 },
  { name: 'red',     color: 0xe03030 },
  { name: 'brown',   color: 0x8a6a5a },
  { name: 'purple',  color: 0x9b8ec4 },
  { name: 'magenta', color: 0xe84f9a },
  { name: 'pink',    color: 0xf0a0c0 },
];
const NC = CLASSES.length, PER = 30, NPT = NC * PER;
const CLS_COLOR = CLASSES.map(c => new THREE.Color(c.color));

/* ── deterministic RNG ─────────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20240917);

/* ── point layout ──────────────────────────────────────────────────────── */
// TOP plane: ten compact, well-separated single-colour clumps spread over the plane
const clump = [
  { x: -2.35, z: -0.10 },   // blue
  { x: -1.95, z:  1.05 },   // olive
  { x: -1.35, z: -1.05 },   // green
  { x: -0.50, z: -1.90 },   // teal
  { x:  0.45, z: -2.05 },   // orange
  { x:  1.15, z: -1.25 },   // red
  { x:  1.00, z: -0.05 },   // brown
  { x:  1.80, z:  0.75 },   // purple
  { x:  2.40, z: -0.55 },   // magenta
  { x:  2.25, z:  1.55 },   // pink
];
// elliptical half-extents of the fully-mixed cloud, per layer (2-D, not a strip)
const SX  = [1.75, 2.10, 2.35, 2.50, 2.50];
const SZ  = [1.15, 1.50, 1.75, 1.90, 1.90];
const JIT = [0.09, 0.22, 0.30, 0.28, 0.00];
const OX  = [0.00, 0.00, -0.15, 0.10, 0.00];
const OZ  = [0.00, 0.10,  0.15, 0.00, 0.00];
const G   = [0.00, 0.14, 0.38, 0.68, 1.00];   // class-grouping strength per layer

const PTS = [];
for (let i = 0; i < NPT; i++) {
  const cls = i % NC;                         // fully interleaved at the bottom
  const u = rnd(), v = rnd();
  const r = Math.sqrt(u), th = v * Math.PI * 2;
  const bx0 = Math.cos(th) * r, bz0 = Math.sin(th) * r;
  const cc = clump[cls];
  const ca = rnd() * Math.PI * 2, cr = Math.sqrt(rnd());
  const top = { x: cc.x + Math.cos(ca) * cr * 0.34, z: cc.z + Math.sin(ca) * cr * 0.30 };
  const layers = [];
  for (let k = 0; k < 5; k++) {
    const g = G[k];
    const jx = (rnd() - 0.5) * JIT[k], jz = (rnd() - 0.5) * JIT[k];
    const cx = bx0 * SX[k] + jx + OX[k];
    const cz = bz0 * SZ[k] + jz + OZ[k];
    layers.push(new THREE.Vector3(
      cx * (1 - g) + top.x * g,
      PLANE_Y[k],
      cz * (1 - g) + top.z * g));
  }
  PTS.push({ cls, layers });
}

/* ── planes ────────────────────────────────────────────────────────────── */
const planes = [];
for (let k = 0; k < 5; k++) {
  const y = PLANE_Y[k];
  const g = new THREE.Group();

  const quadMat = new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0.60,
    depthWrite: false, side: THREE.DoubleSide,
  });
  const quadGeo = new THREE.PlaneGeometry(2 * HALF, 2 * HALF);
  quadGeo.rotateX(-Math.PI / 2);
  const quad = new THREE.Mesh(quadGeo, quadMat);
  quad.position.y = y;
  quad.renderOrder = 2;
  g.add(quad);

  const gridMat = new THREE.LineBasicMaterial({
    color: 0xe2e2e2, transparent: true, opacity: 0.95, depthWrite: false,
  });
  const gridGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-HALF, y + 0.01, 0), new THREE.Vector3(HALF, y + 0.01, 0),
    new THREE.Vector3(0, y + 0.01, -HALF), new THREE.Vector3(0, y + 0.01, HALF),
  ]);
  const grid = new THREE.LineSegments(gridGeo, gridMat);
  grid.renderOrder = 3;
  g.add(grid);

  const borMat = new THREE.LineBasicMaterial({
    color: 0x4f4f4f, transparent: true, opacity: 1, depthWrite: false,
  });
  const corners = [
    new THREE.Vector3(-HALF, y + 0.015, -HALF), new THREE.Vector3(HALF, y + 0.015, -HALF),
    new THREE.Vector3(HALF, y + 0.015, HALF), new THREE.Vector3(-HALF, y + 0.015, HALF),
  ];
  for (const s of [1.0, 0.993, 0.986]) {
    const geo = new THREE.BufferGeometry().setFromPoints(
      corners.map(c => new THREE.Vector3(c.x * s, c.y, c.z * s)));
    const ll = new THREE.LineLoop(geo, borMat);
    ll.renderOrder = 4;
    g.add(ll);
  }
  // transient accent ring — invisible in the default view, pulses on depth change
  const accMat = new THREE.LineBasicMaterial({
    color: 0x2a6fb0, transparent: true, opacity: 0, depthWrite: false,
  });
  const ring = new THREE.Group();
  for (const s of [1.015, 1.007]) {
    const geo = new THREE.BufferGeometry().setFromPoints(
      corners.map(c => new THREE.Vector3(c.x * s, c.y, c.z * s)));
    const ll = new THREE.LineLoop(geo, accMat);
    ll.renderOrder = 5;
    ring.add(ll);
  }
  ring.visible = false;
  g.add(ring);

  scene.add(g);
  planes.push({ group: g, quadMat, borMat, ring, accMat });
}

/* ── scatter points (one InstancedMesh per plane, OPAQUE → saturated) ──── */
const PT_R = 0.135;
const ptGeo = new THREE.SphereGeometry(PT_R, 10, 8);
const dummy = new THREE.Object3D();
const pointMeshes = [];
for (let k = 0; k < 5; k++) {
  const mat = new THREE.MeshBasicMaterial({ transparent: false, depthWrite: true });
  const mesh = new THREE.InstancedMesh(ptGeo, mat, NPT);
  mesh.frustumCulled = false;
  mesh.renderOrder = 1;
  for (let i = 0; i < NPT; i++) {
    const p = PTS[i].layers[k];
    dummy.position.set(p.x, p.y + PT_R * 0.9, p.z);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
    mesh.setColorAt(i, CLS_COLOR[PTS[i].cls]);
  }
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  mesh.userData.planeIdx = k;
  scene.add(mesh);
  pointMeshes.push(mesh);
}

/* ── dashed trajectories: one LineSegments per (class, gap) ────────────── */
const BOW = [0.30, -0.45, -0.40, 0.55];   // waist in the middle, flare at the top
const curveMeshes = [];                   // curveMeshes[gap][cls]
for (let gap = 0; gap < 4; gap++) {
  const perClass = [];
  for (let c = 0; c < NC; c++) perClass.push([]);
  for (let i = 0; i < NPT; i++) {
    const a = PTS[i].layers[gap], b = PTS[i].layers[gap + 1];
    const m1 = a.clone().lerp(b, 1 / 3), m2 = a.clone().lerp(b, 2 / 3);
    const rad = (p) => {
      const r = new THREE.Vector3(p.x, 0, p.z);
      if (r.lengthSq() < 1e-6) r.set(1, 0, 0);
      return r.normalize();
    };
    m1.addScaledVector(rad(m1), BOW[gap]);
    m2.addScaledVector(rad(m2), BOW[gap] * 0.75);
    const curve = new THREE.CatmullRomCurve3([a, m1, m2, b], false, 'catmullrom', 0.5);
    const len = curve.getLength();
    const nd = Math.max(8, Math.round(len / 0.56));
    const sp = curve.getSpacedPoints(nd * 2);
    const arr = perClass[PTS[i].cls];
    for (let j = 0; j < nd; j++) {           // keep alternate spans → dashes
      const p0 = sp[2 * j], p1 = sp[2 * j + 1];
      arr.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
    }
  }
  const row = [];
  for (let c = 0; c < NC; c++) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(perClass[c], 3));
    const mat = new THREE.LineBasicMaterial({
      color: CLS_COLOR[c].clone().lerp(WHITE, 0.12),
      transparent: true, opacity: 0.82, depthWrite: false,
    });
    const ls = new THREE.LineSegments(geo, mat);
    ls.renderOrder = 0;
    scene.add(ls);
    row.push(ls);
  }
  curveMeshes.push(row);
}

/* ── legend column (yaw-billboard: always screen-left, text upright) ───── */
const LEG_R = 8.2;                 // screen-space distance left of the stack axis
const legendGroup = new THREE.Group();
legendGroup.position.set(-LEG_R * Math.SQRT1_2, STACK_CY, LEG_R * Math.SQRT1_2);
legendGroup.rotation.set(0, Math.PI / 4, 0);
scene.add(legendGroup);

function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}
const blackLine = new THREE.LineBasicMaterial({ color: 0x000000 });
const blackFill = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide });
const whiteFill = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });

// one box per ViT-block group, centred between the two planes it maps
const boxWorldY = [0.5 * GAP, 1.5 * GAP, 2.5 * GAP, 3.5 * GAP];
const legendLabels = [];
boxWorldY.forEach((wy) => {
  const ly = wy - STACK_CY;
  const shape = roundedRect(5.0, 1.7, 0.85);
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape), whiteFill);
  fill.position.set(0, ly, 0);
  legendGroup.add(fill);
  const pts2 = shape.getPoints(64);
  for (const s of [1.0, 0.988]) {
    const geo = new THREE.BufferGeometry().setFromPoints(
      pts2.map(p => new THREE.Vector3(p.x * s, p.y * s + ly, 0.02)));
    legendGroup.add(new THREE.LineLoop(geo, blackLine));
  }
  const lab = addLabel('ViT block x3', new THREE.Vector3(0, 0, 0), { fontSize: '13px', color: '#000' });
  lab.div.style.fontFamily = 'ui-monospace, Consolas, monospace';
  legendLabels.push({ lab, ly });
});

// five arrows: one below the first box, three between boxes, one long one on top
const ARROWS = [
  [-1.9, 1.35],
  [boxWorldY[0] + 1.05, boxWorldY[1] - 1.05],
  [boxWorldY[1] + 1.05, boxWorldY[2] - 1.05],
  [boxWorldY[2] + 1.05, boxWorldY[3] - 1.05],
  [boxWorldY[3] + 1.05, 4 * GAP + 2.4],          // spans well above the top box
];
ARROWS.forEach(([y0, y1]) => {
  const w = 0.17, hw = 0.58, hl = 0.72;
  const a0 = y0 - STACK_CY, a1 = y1 - STACK_CY, ah = a1 - hl;
  const s = new THREE.Shape();
  s.moveTo(-w / 2, a0); s.lineTo(w / 2, a0); s.lineTo(w / 2, ah);
  s.lineTo(hw / 2, ah); s.lineTo(0, a1); s.lineTo(-hw / 2, ah);
  s.lineTo(-w / 2, ah); s.closePath();
  const m = new THREE.Mesh(new THREE.ShapeGeometry(s), blackFill);
  m.position.z = 0.01;
  legendGroup.add(m);
});

/* ── camera ────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.92 });
controls.minPolarAngle = THREE.MathUtils.degToRad(25);
controls.maxPolarAngle = THREE.MathUtils.degToRad(80);
document.getElementById('btnReset').style.display = '';

/* ── state ─────────────────────────────────────────────────────────────── */
const STAGES = ['embedding', 'blocks 1-3', 'blocks 4-6', 'blocks 7-9', 'blocks 10-12'];
let depth = 0;
let hoverClass = -1, lockedClass = -1;
let showCurves = true, isolate = false;
let accentPlane = -1, accentT = -1e9;

function pulseAccent(k) { accentPlane = k; accentT = performance.now(); }
function effClass() { return hoverClass >= 0 ? hoverClass : lockedClass; }

const tmpCol = new THREE.Color();
let lastColorKey = null;
function applyState() {
  const hc = effClass();
  // point colours stay fully saturated on EVERY plane; only an explicit class
  // highlight fades the other classes.
  if (hc !== lastColorKey) {
    lastColorKey = hc;
    for (let k = 0; k < 5; k++) {
      const mesh = pointMeshes[k];
      for (let i = 0; i < NPT; i++) {
        const cls = PTS[i].cls;
        const mix = (hc >= 0 && cls !== hc) ? 0.82 : 0;
        tmpCol.copy(CLS_COLOR[cls]).lerp(WHITE, mix);
        mesh.setColorAt(i, tmpCol);
      }
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    }
  }
  for (let k = 0; k < 5; k++) {
    const focus = (k === depth);
    // uniform dark-grey borders as in the source; focus is only a subtle darkening
    planes[k].borMat.color.set(focus ? 0x222222 : 0x4f4f4f);
    planes[k].quadMat.opacity = 0.60;
    planes[k].group.visible = isolate ? focus : true;
    pointMeshes[k].visible = isolate ? focus : true;
  }
  const hotGap = depth - 1;
  for (let gap = 0; gap < 4; gap++) {
    for (let c = 0; c < NC; c++) {
      const ls = curveMeshes[gap][c];
      let op;
      if (hc >= 0) op = (c === hc) ? 1.0 : 0.09;
      else if (hotGap >= 0) op = (gap === hotGap) ? 1.0 : 0.62;
      else op = 0.82;
      ls.material.opacity = op;
      ls.visible = showCurves && !isolate && op > 0.02;
    }
  }
  document.getElementById('depthRead').textContent =
    depth + ' — ' + (depth === 0 ? 'patch embedding' : 'after ' + STAGES[depth]);
  document.getElementById('depthSlider').value = String(depth);
  document.querySelectorAll('#stageBtns button').forEach(b => {
    b.classList.toggle('active', Number(b.dataset.k) === depth);
  });
  document.querySelectorAll('#classList button').forEach(b => {
    b.style.outline = (Number(b.dataset.c) === lockedClass) ? '2px solid #333' : 'none';
  });
}

function setDepth(k) { depth = k; pulseAccent(k); applyState(); }

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const stageBtns = document.getElementById('stageBtns');
STAGES.forEach((s, k) => {
  const b = document.createElement('button');
  b.textContent = s; b.dataset.k = String(k);
  b.style.padding = '3px 6px'; b.style.fontSize = '10px';
  b.addEventListener('click', () => { stopDemo(); setDepth(k); });
  stageBtns.appendChild(b);
});

const classList = document.getElementById('classList');
CLASSES.forEach((c, i) => {
  const b = document.createElement('button');
  b.dataset.c = String(i);
  b.textContent = c.name;
  b.style.cssText = 'padding:2px 6px;font-size:10px;border-radius:9px;color:#fff;border:1px solid #0002;' +
    'background:#' + c.color.toString(16).padStart(6, '0');
  b.addEventListener('mouseenter', () => { hoverClass = i; applyState(); });
  b.addEventListener('mouseleave', () => { hoverClass = -1; applyState(); });
  b.addEventListener('click', () => { lockedClass = (lockedClass === i) ? -1 : i; applyState(); });
  classList.appendChild(b);
});
document.getElementById('btnClearClass').addEventListener('click', () => {
  lockedClass = -1; hoverClass = -1; applyState();
});

document.getElementById('depthSlider').addEventListener('input', (e) => {
  stopDemo(); setDepth(Number(e.target.value));
});
document.getElementById('showCurves').addEventListener('change', (e) => {
  showCurves = e.target.checked; applyState();
});
document.getElementById('isoPlane').addEventListener('change', (e) => {
  isolate = e.target.checked; applyState();
});
document.getElementById('showLegend').addEventListener('change', (e) => {
  legendGroup.visible = e.target.checked;
  legendLabels.forEach(({ lab }) => { lab.div.style.visibility = e.target.checked ? '' : 'hidden'; });
});

/* ── 3D hover on the point clouds ──────────────────────────────────────── */
const rc = new THREE.Raycaster();
const pv = new THREE.Vector2();
canvas.addEventListener('pointermove', (ev) => {
  const r = canvas.getBoundingClientRect();
  pv.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  pv.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  rc.setFromCamera(pv, camera);
  const hits = rc.intersectObjects(pointMeshes.filter(m => m.visible), false);
  let c = -1;
  if (hits.length && hits[0].instanceId != null) c = PTS[hits[0].instanceId].cls;
  if (c !== hoverClass) { hoverClass = c; applyState(); }
  if (c >= 0) showTooltip('class: ' + CLASSES[c].name + '  (hover traces it through every plane)', ev);
});
canvas.addEventListener('pointerleave', () => { hoverClass = -1; applyState(); });

/* ── demo ──────────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Patch embeddings (bottom plane)', narration: 'At the output of patch embedding the tokens form one dense, thoroughly interleaved cloud: every colour sits next to every other colour and no class is linearly separable.', depth: 0 },
  { title: 'After the first three ViT blocks', narration: 'Follow the dashed bundles up one stage. The cloud widens across the plane, but the colours are still mixed — three blocks alone barely untangle the classes.', depth: 1 },
  { title: 'Mid-network (blocks 4-6)', narration: 'By the middle plane, same-colour neighbourhoods are clearly emerging and the cloud occupies more of the plane, yet neighbouring classes still overlap.', depth: 2 },
  { title: 'Late blocks (7-9)', narration: 'Same-colour points pull together into recognisable groups while the trajectories fan outward: the largest reorganisation of the representation happens in the later blocks.', depth: 3 },
  { title: 'Final representation (top plane)', narration: 'On the top plane each class has collapsed into its own compact, single-coloured clump spread far from the others — twelve transformer blocks turn a tangled distribution into a class-separated one.', depth: 4 },
];
let stepIdx = 0, demoTimer = null;
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('narrTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + ' · ' + s.title;
  document.getElementById('narr').textContent = s.narration;
  setDepth(s.depth);
}
function stopDemo() {
  if (demoTimer) { clearInterval(demoTimer); demoTimer = null; }
  document.getElementById('btnPlay').textContent = '▶ Play demo';
}
document.getElementById('btnPlay').addEventListener('click', () => {
  if (demoTimer) { stopDemo(); return; }
  goToStep(0);
  document.getElementById('btnPlay').textContent = '❚❚ Pause';
  demoTimer = setInterval(() => goToStep(stepIdx + 1), 4200);
});
document.getElementById('btnNext').addEventListener('click', () => { stopDemo(); goToStep(stepIdx + 1); });

/* ── per-frame: legend billboard + transient accent fade ───────────────── */
const tmpV = new THREE.Vector3();
(function tick() {
  requestAnimationFrame(tick);

  const dx = camera.position.x - controls.target.x;
  const dz = camera.position.z - controls.target.z;
  const phi = Math.atan2(dx, dz);                 // horizontal camera bearing
  legendGroup.rotation.set(0, phi, 0);            // panel normal → camera (yaw only)
  legendGroup.position.set(-LEG_R * Math.cos(phi), STACK_CY, LEG_R * Math.sin(phi));
  legendGroup.updateMatrixWorld();
  for (const { lab, ly } of legendLabels) {
    tmpV.set(0, ly, 0.03);
    legendGroup.localToWorld(tmpV);
    lab.pos.copy(tmpV);
  }

  const age = (performance.now() - accentT) / 1300;
  const o = Math.max(0, 1 - age);
  for (let k = 0; k < 5; k++) {
    const on = (k === accentPlane) && o > 0.02;
    planes[k].ring.visible = on;
    planes[k].accMat.opacity = on ? o * 0.9 : 0;
  }
})();

goToStep(0);
